"use strict";
import { AnimatedPopover, Flex, Popover, Text, styled } from "ui/src";
import { ChevronDown } from "react-feather";
import { useState } from "react";
import { useSeason } from "../context/SeasonContext";
export default function SeasonsDropdown() {
  const [isOpen, setIsOpen] = useState(false);
  const { selectedSeason, setSelectedSeason } = useSeason();
  const avaiableSeasons = ["Season 1", "Season 2"];
  const Item = styled(Flex, {
    row: true,
    gap: "$gap8",
    alignItems: "center",
    py: "$padding8",
    px: "$spacing16",
    borderRadius: "$rounded8",
    cursor: "pointer",
    hoverStyle: {
      backgroundColor: "$surface2Hovered"
    }
  });
  const handleSeasonChange = (season) => {
    setTimeout(() => setSelectedSeason(season), 200);
  };
  return <Flex maxWidth={768} mx={"auto"} width={"100%"} row justifyContent="flex-start">
      <Popover allowFlip onOpenChange={setIsOpen}>
        <Popover.Trigger
    py={"$spacing12"}
    px={"$spacing12"}
    gap={"$gap8"}
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="space-between"
    alignItems="center"
    borderRadius={"$rounded12"}
    cursor="pointer"
  >
          <Flex row gap={"$gap4"} alignItems="center">
            <Text variant="buttonLabel3">{selectedSeason}</Text>
            <Flex transform={isOpen ? "rotate(180deg)" : "rotate(0deg)"}>
              <ChevronDown size={16} />
            </Flex>
          </Flex>
        </Popover.Trigger>
        <AnimatedPopover isOpen={isOpen} marginTop={"$spacing8"}>
          <Popover.Close>
            <Flex>
              {avaiableSeasons.map((season) => <Item onPress={() => handleSeasonChange(season)}>
                  <Flex
    opacity={selectedSeason === season ? 1 : 0}
    height={7}
    width={7}
    borderRadius={"$roundedFull"}
    backgroundColor={"$accent1"}
  />
                  <Text>{season}</Text>
                </Item>)}
            </Flex>
          </Popover.Close>
        </AnimatedPopover>
      </Popover>
    </Flex>;
}
